const localeProfileItem = $('Loop Over Items').item.json;
const blueprintDoc = $('Get story blueprint').item.json;
const bibleDoc = $('Get story bible').item.json;

const storyId = localeProfileItem.story_id;
const targetCulture = localeProfileItem.target_culture;

if (!blueprintDoc || !blueprintDoc.blueprint) {
  throw new Error(`Blueprint missing for story_id="${storyId}" — check story_blueprints collection.`);
}
if (!bibleDoc || !bibleDoc.bible) {
  throw new Error(`Bible missing for story_id="${storyId}" — check story_bibles collection.`);
}
if (!localeProfileItem.locale_profile) {
  throw new Error(`locale_profile missing on loop item for story_id="${storyId}", target_culture="${targetCulture}".`);
}

return {
  story_id: storyId,
  target_culture: targetCulture,
  locale_profile: localeProfileItem.locale_profile,
  blueprint: blueprintDoc.blueprint,
  bible: bibleDoc.bible
};

const data = $input.item.json; // story_id, target_culture, locale_profile, blueprint, bible

const clean = (str) => (str || '')
  .toString()
  .replace(/\\/g, '')
  .replace(/"/g, "'")
  .replace(/\n/g, ' ')
  .replace(/\r/g, '')
  .trim();

const cleanArray = (arr) => (arr || []).map(x => clean(typeof x === 'string' ? x : JSON.stringify(x)));

const bp = data.blueprint || {};
const bible = data.bible || {};
const lp = data.locale_profile || {};

// --- Identité protégée (jamais adaptée) ---
const characterNamesStr = (bible.characters || [])
  .map(c => c.name + " (" + c.role + ")")
  .join(", ");

const relationshipsStr = (bible.relationships || [])
  .filter(r => r.is_protected)
  .map(r => r.source_character_id + " -> " + r.target_character_id + " (" + r.relationship_type + "): " + clean(r.description))
  .join("; ");

const moralStr = cleanArray(bp.core_moral).join("; ");
const worldRulesStr = (bible.world_rules || [])
  .filter(r => r.is_protected)
  .map(r => clean(r.rule))
  .join("; ");

const continuityStr = cleanArray(bible.continuity_constraints).join("; ");

// --- Structure narrative, répartie en 3 actes selon les phases du Blueprint ---
const structure = bp.story_structure || [];
const introPhases = ["setup", "inciting_incident"];
const devPhases = ["rising_action", "climax"];
const endPhases = ["falling_action", "resolution"];

const phaseSummary = (phases) => structure
  .filter(s => phases.includes(s.phase))
  .sort((a, b) => a.sequence - b.sequence)
  .map(s => clean(s.summary) + " (" + s.narrative_function + ")")
  .join(" -> ");

const introOutline = phaseSummary(introPhases);
const devOutline = phaseSummary(devPhases);
const endOutline = phaseSummary(endPhases);

const keyEventsStr = (bp.key_events || [])
  .filter(e => e.is_protected)
  .map(e => clean(e.description) + " [must appear, phase-relevant]")
  .join("; ");

// --- Éléments culturels cibles (Locale Profile) ---
const settingStr = JSON.stringify(lp.setting || {});
const socialContextStr = JSON.stringify(lp.social_context || {});
const culturalElementsStr = JSON.stringify(lp.cultural_elements || {});
const languageStyle = lp.language_style || {};
const mappingsStr = (lp.cultural_mappings || [])
  .map(m => clean(m.story_element) + " -> " + clean(m.target_representation) + " (" + clean(m.adaptation_reason) + ")")
  .join("; ");
const preservationRulesStr = cleanArray(lp.preservation_rules).join("; ");
const forbiddenStr = cleanArray(lp.forbidden_adaptations).join("; ");

const outputSchema = "{" +
  "\"story_id\": \"\", " +
  "\"target_culture\": \"\", " +
  "\"title\": \"\", " +
  "\"story_parts\": {" +
    "\"intro\": \"\", " +
    "\"developpement\": \"\", " +
    "\"conclusion\": \"\"" +
  "}" +
"}";

const prompt =
  "You are a children's story writer performing a CULTURAL ADAPTATION, not a translation. " +
  "You write the full prose text of the story, split into exactly three parts: intro, developpement, conclusion. " +
  "Target audience: " + clean(bp.target_audience) + ". Target culture: " + clean(data.target_culture) + ". " +

  "CHARACTER NAME RULE: These character names must appear EXACTLY as given, never renamed or translated: " + characterNamesStr + ". " +

  "PROTECTED — MUST BE PRESERVED EXACTLY AS NARRATIVE FUNCTION (surface details may be localized, meaning may not change): " +
  "Relationships: " + relationshipsStr + ". " +
  "Core moral: " + moralStr + ". " +
  "World rules: " + worldRulesStr + ". " +
  "Continuity constraints: " + continuityStr + ". " +
  "Key events that must occur, in order: " + keyEventsStr + ". " +

  "NARRATIVE OUTLINE (do not deviate from this order/function, only localize surface details): " +
  "INTRO covers: " + introOutline + ". " +
  "DEVELOPPEMENT covers: " + devOutline + ". " +
  "CONCLUSION covers: " + endOutline + ". " +

  "CULTURAL ADAPTATION TO APPLY (from the Locale Profile — use this to decide settings, food, clothing, forms of address, daily life details): " +
  "Setting: " + settingStr + ". " +
  "Social context: " + socialContextStr + ". " +
  "Cultural elements: " + culturalElementsStr + ". " +
  "Specific element mappings to apply: " + mappingsStr + ". " +

  "LANGUAGE RULE — CRITICAL: The story text (title, intro, developpement, conclusion) must ALWAYS be written in ENGLISH, regardless of the target culture's native language. " +
  "Do not write in " + clean(languageStyle.language || "the target culture's language") + " and do not mix languages into the prose. " +
  "Cultural adaptation applies to SETTING, CONTENT, and TONE — never to the language the story is written in. " +
  "Language register to emulate (in English): " + clean(languageStyle.register) + ". " +
  "Local expressions / forms of address from the Locale Profile are a source of INSPIRATION for tone and flavor only — render their spirit or an equivalent in English (e.g. an English term of endearment, an English rendering of a greeting custom), never insert them verbatim in a non-English script or language. " +
  "The only exception: a single well-known culturally iconic term (a specific food or garment name) may be used as an English-text loanword, the way an English-language children's book would use it, if it aids the cultural flavor. " +
  "Reference expressions listed (for tone inspiration only, do not transcribe verbatim): " + cleanArray(languageStyle.local_expressions).join(", ") + ". " +

  "HARD CONSTRAINTS: " +
  "Preservation rules — never violate: " + preservationRulesStr + ". " +
  "Forbidden adaptations — never do this: " + forbiddenStr + ". " +
  "Never rename a protected character. Never change the moral or the outcome of a protected relationship. " +
  "Write natural, flowing prose appropriate for the target age group — not a summary, not bullet points. " +
  "Each of intro/developpement/conclusion must be a self-contained block of English prose (a few paragraphs each). " +
  "do not change the title keep it the original one for all culture"
+
  "Respond ONLY with valid JSON matching exactly this schema, no extra text, no markdown fences, no reasoning shown in the output: " + outputSchema;

const fireworks_body = JSON.stringify({
  model: "accounts/fireworks/models/deepseek-v4p1-flash",
  max_tokens: 8000,
  temperature: 0.4,
  reasoning_effort: "low",
  messages: [{ role: "user", content: prompt }]
});

return {
  story_id: data.story_id,
  target_culture: data.target_culture,
  story_gen_prompt: prompt,
  fireworks_body
};

const response = $input.item.json;
const promptData = $('Build Story Generation Prompt').item.json;

const choice = response.choices?.[0];
const finishReason = choice?.finish_reason;

let rawText = "";
try {
  rawText = choice.message.content;
} catch (e) {
  return {
    parse_error: true,
    error_message: "No content in LLM response (exception): " + e.message,
    raw_response: JSON.stringify(response),
    story_id: promptData.story_id,
    target_culture: promptData.target_culture
  };
}

if (typeof rawText !== 'string' || rawText.trim() === '') {
  return {
    parse_error: true,
    error_message: "LLM response content is empty or not a string (finish_reason: " + finishReason + ")",
    raw_response: JSON.stringify(response),
    story_id: promptData.story_id,
    target_culture: promptData.target_culture
  };
}

if (finishReason === 'length') {
  return {
    parse_error: true,
    error_message: "LLM response was truncated (finish_reason=length). Increase max_tokens or reduce reasoning_effort.",
    raw_response: rawText.slice(-300),
    story_id: promptData.story_id,
    target_culture: promptData.target_culture
  };
}

const cleanedText = rawText
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

function tryFixCommonJsonErrors(text) {
  let fixed = text;
  fixed = fixed.replace(/\]\]/g, ']');
  fixed = fixed.replace(/\}\}(\s*,\s*")/g, '}$1');
  fixed = fixed.replace(/\\"\]/g, '"]');
  fixed = fixed.replace(/,(\s*[\}\]])/g, '$1');
  return fixed;
}

let storyOutput;
let usedFix = false;

try {
  storyOutput = JSON.parse(cleanedText);
} catch (firstError) {
  try {
    storyOutput = JSON.parse(tryFixCommonJsonErrors(cleanedText));
    usedFix = true;
  } catch (secondError) {
    // Filet de sécurité supplémentaire : extraction par première/dernière accolade,
    // au cas où il reste du texte parasite avant/après malgré le nettoyage markdown.
    const firstBrace = cleanedText.indexOf('{');
    const lastBrace = cleanedText.lastIndexOf('}');
    if (firstBrace !== -1 && lastBrace !== -1) {
      try {
        storyOutput = JSON.parse(cleanedText.slice(firstBrace, lastBrace + 1));
        usedFix = true;
      } catch (thirdError) {
        return {
          parse_error: true,
          error_message: "JSON parse failed after auto-fix and brace-extraction: " + thirdError.message,
          raw_response: cleanedText.slice(0, 500),
          story_id: promptData.story_id,
          target_culture: promptData.target_culture
        };
      }
    } else {
      return {
        parse_error: true,
        error_message: "JSON parse failed, no JSON object found: " + secondError.message,
        raw_response: cleanedText.slice(0, 500),
        story_id: promptData.story_id,
        target_culture: promptData.target_culture
      };
    }
  }
}

return {
  parse_error: false,
  auto_fixed: usedFix,
  story_id: promptData.story_id,
  target_culture: promptData.target_culture,
  story_output: storyOutput
};

const item = $input.item.json;
const output = item.story_output || {};
const parts = output.story_parts || {};

const requiredParts = ["intro", "developpement", "conclusion"];

const emptyParts = requiredParts.filter(p =>
  typeof parts[p] !== 'string' || parts[p].trim() === ''
);

const valid = emptyParts.length === 0;

return {
  ...item,
  story_valid: valid,
  story_validation_errors: emptyParts.map(p => `story_parts.${p} is empty or missing`)
};

const item = $json;

return [{
  json: {
    story_id: item.story_id,
    target_culture: item.target_culture,
    document_id: item.story_id + '_' + item.target_culture,
    title: item.story_output?.title || '',
    story_parts: item.story_output?.story_parts || {},
    story_valid: item.story_valid,
    status: 'ready_for_validation',
    created_at: new Date().toISOString()
  }
}];

const item = $json;
const MAX_RETRIES = 3;

const retryCount = (item.retry_count || 0) + 1;

// Trace la cause pour le log final, sans dépendre d'un champ qui n'existe
// que sur une seule des deux branches (parse_error vs story_valid)
const failureReason = item.parse_error
  ? ('parse_error: ' + (item.error_message || 'unknown parse error'))
  : ('validation_error: ' + (item.story_validation_errors || []).join(' | '));

return {
  ...item,
  retry_count: retryCount,
  retry_exceeded: retryCount >= MAX_RETRIES,
  last_failure_reason: failureReason
};

const item = $json;

return [{
  json: {
    log_id: Date.now().toString(),
    workflow: 'story_generation',
    story_id: item.story_id,
    target_culture: item.target_culture,
    step: item.parse_error ? 'llm_parsing' : 'story_validation',
    status: 'failed',
    retry_count: item.retry_count,
    message: 'Story generation failed after max retries: ' + item.last_failure_reason,
    created_at: new Date().toISOString()
  }
}];
